import 'custom_split_config.dart';

/// Representation of a single slice generated by the Custom Split engine.
class CustomClipItem {
  final int index;
  final String formattedName;
  final double startSeconds;
  final double endSeconds;
  final double durationSeconds;
  final int estimatedSizeBytes;
  final bool isKeyframeAccurate;
  final String? customName;

  const CustomClipItem({
    required this.index,
    required this.formattedName,
    required this.startSeconds,
    required this.endSeconds,
    required this.durationSeconds,
    required this.estimatedSizeBytes,
    required this.isKeyframeAccurate,
    this.customName,
  });

  String get displayName =>
      (customName != null && customName!.trim().isNotEmpty)
      ? customName!.trim()
      : formattedName;

  CustomClipItem copyWith({
    int? index,
    String? formattedName,
    double? startSeconds,
    double? endSeconds,
    double? durationSeconds,
    int? estimatedSizeBytes,
    bool? isKeyframeAccurate,
    String? customName,
  }) {
    return CustomClipItem(
      index: index ?? this.index,
      formattedName: formattedName ?? this.formattedName,
      startSeconds: startSeconds ?? this.startSeconds,
      endSeconds: endSeconds ?? this.endSeconds,
      durationSeconds: durationSeconds ?? this.durationSeconds,
      estimatedSizeBytes: estimatedSizeBytes ?? this.estimatedSizeBytes,
      isKeyframeAccurate: isKeyframeAccurate ?? this.isKeyframeAccurate,
      customName: customName ?? this.customName,
    );
  }

  Map<String, dynamic> toJson() => {
    'index': index,
    'formattedName': formattedName,
    'startSeconds': startSeconds,
    'endSeconds': endSeconds,
    'durationSeconds': durationSeconds,
    'estimatedSizeBytes': estimatedSizeBytes,
    'isKeyframeAccurate': isKeyframeAccurate,
    'customName': customName,
  };

  factory CustomClipItem.fromJson(Map<String, dynamic> json) => CustomClipItem(
    index: json['index'] as int,
    formattedName: json['formattedName'] as String,
    startSeconds: (json['startSeconds'] as num).toDouble(),
    endSeconds: (json['endSeconds'] as num).toDouble(),
    durationSeconds: (json['durationSeconds'] as num).toDouble(),
    estimatedSizeBytes: (json['estimatedSizeBytes'] as num?)?.toInt() ?? 0,
    isKeyframeAccurate: json['isKeyframeAccurate'] as bool? ?? true,
    customName: json['customName'] as String?,
  );
}

/// Complete plan specification for a custom video split job.
class CustomClipPlan {
  final String originalVideoName;
  final String baseName;
  final double totalDurationSeconds;
  final CustomSplitMode splitMode;
  final SplitMethod splitMethod;
  final List<CustomClipItem> items;
  final int estimatedTotalSizeBytes;

  const CustomClipPlan({
    required this.originalVideoName,
    required this.baseName,
    required this.totalDurationSeconds,
    required this.splitMode,
    required this.splitMethod,
    required this.items,
    required this.estimatedTotalSizeBytes,
  });

  int get totalParts => items.length;

  double get coveredDuration =>
      items.fold(0.0, (sum, item) => sum + item.durationSeconds);

  CustomClipPlan copyWith({
    String? originalVideoName,
    String? baseName,
    double? totalDurationSeconds,
    CustomSplitMode? splitMode,
    SplitMethod? splitMethod,
    List<CustomClipItem>? items,
    int? estimatedTotalSizeBytes,
  }) {
    return CustomClipPlan(
      originalVideoName: originalVideoName ?? this.originalVideoName,
      baseName: baseName ?? this.baseName,
      totalDurationSeconds: totalDurationSeconds ?? this.totalDurationSeconds,
      splitMode: splitMode ?? this.splitMode,
      splitMethod: splitMethod ?? this.splitMethod,
      items: items ?? this.items,
      estimatedTotalSizeBytes:
          estimatedTotalSizeBytes ?? this.estimatedTotalSizeBytes,
    );
  }

  Map<String, dynamic> toJson() => {
    'originalVideoName': originalVideoName,
    'baseName': baseName,
    'totalDurationSeconds': totalDurationSeconds,
    'splitMode': splitMode.name,
    'splitMethod': splitMethod.name,
    'items': items.map((i) => i.toJson()).toList(),
    'estimatedTotalSizeBytes': estimatedTotalSizeBytes,
  };

  factory CustomClipPlan.fromJson(Map<String, dynamic> json) => CustomClipPlan(
    originalVideoName: json['originalVideoName'] as String,
    baseName: json['baseName'] as String,
    totalDurationSeconds: (json['totalDurationSeconds'] as num).toDouble(),
    splitMode: CustomSplitMode.values.byName(
      json['splitMode'] as String? ?? 'byDuration',
    ),
    splitMethod: SplitMethod.values.byName(
      json['splitMethod'] as String? ?? 'fast',
    ),
    items: (json['items'] as List<dynamic>)
        .map((e) => CustomClipItem.fromJson(e as Map<String, dynamic>))
        .toList(),
    estimatedTotalSizeBytes:
        (json['estimatedTotalSizeBytes'] as num?)?.toInt() ?? 0,
  );
}
